 srows("DL02").forEach(function(r){if(hit(r.full_name,r.phone_number,r.lead_id))res.push({t:"Lead",id:r.lead_id,nm:r.full_name,sub:(elabel(r.lead_status)||"-")+" - "+(r.phone_number||"-"),na:r.next_action,pid:r.lead_id})});
