  h+='<div style="padding-top:4px"><button class="btn sm" onclick="uiSet(\'logo\',\'\');reRender(CUR)"><i class="ti ti-restore"></i>Dùng logo mặc định</button></div>';
  h+='</div></div></div><div>';
