 var rev=0;rows("DL07").forEach(function(p){var e=find("DL06","enrollment_id",p.enrollment_id);if(e&&String(e.course_id||"")===id)rev+=num(p.amount)});
 var debt=live.reduce(function(a,e){return a+num(e.remaining_amount)},0);
